        if dataset_paths:
            unique_sources: list[Path] = []
            seen: set[str] = set()
            for candidate in dataset_paths:
                resolved = candidate
                try:
                    key = str(candidate.resolve()) if candidate.exists() else str(candidate)
                except OSError as e:
                    logger.debug(f"OSError: {e}")
                    logger.warning(f"OSError: {e}", exc_info=True)
                    key = str(candidate)
                if key in seen:
                    continue
                seen.add(key)
