        try:
            acc = float(token_accuracy(preds, tgt))  # type: ignore[call-arg]
        except Exception:
            logger.warning("Exception occurred", exc_info=True)
            try:
                acc = float(token_accuracy(logits, targets))  # type: ignore[call-arg]
            except Exception:
                logger.warning("Exception occurred", exc_info=True)
                acc = float("nan")

