        logits = None

        def _compute_loss(_):
            nonlocal logits
            logits = model(inputs)
            return F.cross_entropy(logits.reshape(-1, cfg.vocab_size), targets.reshape(-1))

        loss_val = codex_train_step(
            model,
            opt,
            sched,
            _compute_loss,
            None,
            accum_steps=grad_accum,
            precision=precision,
            grad_clip=grad_clip,
        )

