            with torch.no_grad():
                v_logits = model(val_inputs)
                v_loss = F.cross_entropy(
                    v_logits.reshape(-1, cfg.vocab_size),
                    val_targets.reshape(-1),
                )
                v_preds = v_logits.argmax(dim=-1).reshape(-1).tolist()
