    if val_split + test_split >= 1.0:
        print("Warning: val_split + test_split >= 1; clamping to 0")
        val_split = 0.0
        test_split = 0.0
    n_val = int(total * val_split)
    n_test = int(total * test_split)
    n_train = total - n_val - n_test
