    val_split = max(0.0, min(0.999, float(val_split)))
    test_split = max(0.0, min(0.999, float(test_split)))
    if val_split + test_split >= 1.0:
        print("Warning: val_split + test_split >= 1; clamping to 0")
        val_split = 0.0
