            emit_validation_metric_record(
                str(metrics_file),
                {
                    "epoch": epoch + 1,
                    "split": "val",
                    "token_accuracy": v_acc,
                    "perplexity": v_ppl,
                    "config": {
                        "val_split": val_split,
                        "test_split": test_split,
                        "EPOCH": epoch + 1,
                    },
                },
            )

